        TextStyle ts = buildTextStyle(6, "RIGHT", 0);
        String text = "xyz";
        CharSequence result = ts.pad(false, text);

        Object rightEnum = getAlignmentConstant("RIGHT");
        if (rightEnum != null) {
            String s = result.toString();
            assertTrue(s.endsWith(text));
        } else {
            // Fallback: ensure padded length equals maxWidth and contains original text
            assertEquals(6, result.length());
            assertTrue(result.toString().contains(text));
        }
