public class PadTests {

    private static final String[] MAX_WIDTH_NAMES = {"maxWidth", "width", "setMaxWidth", "setWidth"};
    private static final String[] INDENT_NAMES = {"indent", "setIndent", "padding", "indentation"};
    private static final String[] ALIGNMENT_NAMES = {"alignment", "align", "setAlignment", "withAlignment"};

    private Object getAlignmentConstant(final String name) {
        try {
            Class<?> enumClass = Class.forName(TextStyle.class.getName() + "$Alignment");
            Field f = enumClass.getField(name);
            return f.get(null);
        } catch (Exception e) {
            return null;
        }
    }

    private boolean setBuilderValue(Object builder, String[] methodNames, Object arg) {
        Class<?> cls = builder.getClass();
        // Try direct method with exact param type
        for (String name : methodNames) {
            try {
                Method m = cls.getMethod(name, arg.getClass());
                m.invoke(builder, arg);
                return true;
            } catch (Exception ignored) {
            }
        }
        // If arg is Integer, try primitive int parameter
        if (arg instanceof Integer) {
            int v = (Integer) arg;
            for (String name : methodNames) {
                try {
                    Method m = cls.getMethod(name, int.class);
                    m.invoke(builder, v);
                    return true;
                } catch (Exception ignored) {
                }
            }
        }
        return false;
    }

    private TextStyle buildTextStyle(Integer maxWidth, String alignmentName, Integer indent) {
        try {
            // Get builder
            Object builder = TextStyle.class.getMethod("builder").invoke(null);

            // Set maxWidth if provided
            if (maxWidth != null) {
                setBuilderValue(builder, MAX_WIDTH_NAMES, maxWidth);
            }

            // Set alignment if provided
            Object alignConst = null;
            if (alignmentName != null) {
                alignConst = getAlignmentConstant(alignmentName);
            }
            if (alignConst != null) {
                setBuilderValue(builder, ALIGNMENT_NAMES, alignConst);
            }

            // Set indent if provided
            if (indent != null) {
                setBuilderValue(builder, INDENT_NAMES, indent);
            }

            // Build TextStyle
            try {
                Method getMethod = builder.getClass().getMethod("get");
                TextStyle ts = (TextStyle) getMethod.invoke(builder);
                return ts;
