        Options result = options.addOptionGroup(group);
        assertNotNull(result);
        assertSame(options, result);

        Option retrieved = options.getOption("x");
        assertNotNull(retrieved);
        assertEquals("x", retrieved.getOpt());
    }
}

package org.apache.commons.cli;

import org.junit.Test;

import static org.junit.Assert.*;

public class AddOptionGroupTests {

    @Test(expected = IllegalArgumentException.class)
    public void testAddOptionGroupNullThrows() {
        Options options = new Options();
        options.addOptionGroup(null);
    }

    @Test
    public void testAddOptionGroupAddsOptionsAndMarksNotRequired() {
        Options options = new Options();

        Option o1 = new Option("a", "alpha", false, "desc1");
        Option o2 = new Option("b", "beta", false, "desc2");

        OptionGroup group = new OptionGroup();
        group.addOption(o1);
        group.addOption(o2);
        group.setRequired(true);

        Options result = options.addOptionGroup(group);
        assertNotNull(result);
        assertSame(options, result);

        // Ensure options are added and retrievable
        assertNotNull(options.getOption("a"));
        assertNotNull(options.getOption("alpha"));
        assertNotNull(options.getOption("b"));
        assertNotNull(options.getOption("beta"));

        // Options should not be marked as required when they belong to a required group
        assertFalse(options.getOption("a").isRequired());
        assertFalse(options.getOption("alpha").isRequired());
        assertFalse(options.getOption("b").isRequired());
        assertFalse(options.getOption("beta").isRequired());
    }

    @Test
    public void testAddOptionGroupWithoutNullDoesNotModifyExistingOptions() {
        Options options = new Options();

        Option o1 = new Option("x", "xlong", false, "desc");
        options.addOption(o1);

        OptionGroup group = new OptionGroup();
        group.addOption(o1);
        group.setRequired(false);

        Options result = options.addOptionGroup(group);
        assertNotNull(result);
        assertSame(options, result);

        Option retrieved = options.getOption("x");
        assertNotNull(retrieved);
        assertEquals("x", retrieved.getOpt());
    }
}
